import { useState } from 'react';
import {
  JxButton,
  JxInputField,
  JxSelect,
  JxStepper,
  JxTable,
} from '@jinx-ui/react';

export interface RegistrationValues {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
}

export interface RegistrationWizardProps {
  onSubmit: (values: RegistrationValues) => void;
}

const emptyValues: RegistrationValues = {
  name: '',
  email: '',
  phone: '',
  country: 'ru',
  city: '',
  street: '',
  zip: '',
};

const countries = [
  { value: 'ru', label: 'Россия' },
  { value: 'kz', label: 'Казахстан' },
  { value: 'by', label: 'Беларусь' },
  { value: 'am', label: 'Армения' },
];

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<RegistrationValues>(emptyValues);

  const setField = (field: keyof RegistrationValues, value: string) => {
    setValues((current) => ({ ...current, [field]: value }));
  };

  const countryLabel =
    countries.find((country) => country.value === values.country)?.label ?? '';

  const contactsFilled =
    values.name.trim() !== '' && values.email.trim() !== '';
  const addressFilled = values.city.trim() !== '' && values.street.trim() !== '';
  const canGoNext = step === 0 ? contactsFilled : addressFilled;

  return (
    <div style={{ display: 'grid', gap: '24px' }}>
      <JxStepper steps={steps} current={step} />

      {step === 0 ? (
        <div style={{ display: 'grid', gap: '16px' }}>
          <JxInputField
            label="Имя и фамилия"
            required
            value={values.name}
            onChange={(event) => setField('name', event.target.value)}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={values.email}
            onChange={(event) => setField('email', event.target.value)}
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            placeholder="900 000-00-00"
            helperText="Понадобится только для связи по заказу"
            value={values.phone}
            onChange={(event) => setField('phone', event.target.value)}
          />
        </div>
      ) : null}

      {step === 1 ? (
        <div style={{ display: 'grid', gap: '16px' }}>
          <JxSelect
            label="Страна"
            options={countries}
            value={values.country}
            onValueChange={(value) => setField('country', value)}
          />
          <JxInputField
            label="Город"
            required
            value={values.city}
            onChange={(event) => setField('city', event.target.value)}
          />
          <JxInputField
            label="Улица и дом"
            required
            value={values.street}
            onChange={(event) => setField('street', event.target.value)}
          />
          <JxInputField
            label="Индекс"
            inputMode="numeric"
            value={values.zip}
            onChange={(event) => setField('zip', event.target.value)}
          />
        </div>
      ) : null}

      {step === 2 ? (
        <JxTable>
          <tbody>
            <tr>
              <th scope="row">Имя и фамилия</th>
              <td>{values.name}</td>
            </tr>
            <tr>
              <th scope="row">Электронная почта</th>
              <td>{values.email}</td>
            </tr>
            <tr>
              <th scope="row">Телефон</th>
              <td>{values.phone ? `+7 ${values.phone}` : '—'}</td>
            </tr>
            <tr>
              <th scope="row">Страна</th>
              <td>{countryLabel}</td>
            </tr>
            <tr>
              <th scope="row">Город</th>
              <td>{values.city}</td>
            </tr>
            <tr>
              <th scope="row">Улица и дом</th>
              <td>{values.street}</td>
            </tr>
            <tr>
              <th scope="row">Индекс</th>
              <td>{values.zip || '—'}</td>
            </tr>
          </tbody>
        </JxTable>
      ) : null}

      <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end' }}>
        <JxButton
          variant="ghost"
          disabled={step === 0}
          onClick={() => setStep(step - 1)}
        >
          Назад
        </JxButton>
        {step === 2 ? (
          <JxButton variant="primary" onClick={() => onSubmit(values)}>
            Отправить
          </JxButton>
        ) : (
          <JxButton
            variant="primary"
            disabled={!canGoNext}
            onClick={() => setStep(step + 1)}
          >
            Дальше
          </JxButton>
        )}
      </div>
    </div>
  );
}

export default RegistrationWizard;

